window.__APP_CHUNKS=window.__APP_CHUNKS||[];window.__APP_CHUNKS[9]="\", \"targets\": [\"Кутум\", \"Вобла / другие карповые\"], \"facts\": [\"22–23.08.2020 — очень сильный кратковременный клёв; много кутума и воблы.\", \"Берег каменисто-песчаный; заброс требовался за крупные выступающие камни.\", \"5–7.10.2025 на той же точке было заметно хуже.\"], \"hypothesis\": \"В 2020 штормовая обстановка и волна могли концентрировать корм и рыбу у каменисто-песчаной кромки.\", \"next\": \"Сопоставить 21–24.08.2020 и 05–07.10.2025: ветер, волна, SST, давление и осадки.\"}, {\"name\": \"Сулак / район Нечаевки\", \"region\": \"Дагестан\", \"coords\": \"точная точка ещё не закреплена\", \"status\": \"Неудачная разведка\", \"image\": \"data:image/webp;base64,\", \"targets\": [\"Щука\"], \"facts\": [\"05–11.10.2025: высокая вода, очень сильное течение, серая водная масса.\", \"Поклёвок не было.\", \"Местный рыбак говорил о щуке и весеннем сезоне, но сам ушёл, увидев состояние воды.\"], \"hypothesis\": \"Ключевой фактор — не октябрь как таковой, а гидрология и режим сбросов.\", \"next\": \"Реконструировать уровни/расход и работу гидроузлов на даты поездки.\"}], \"methods\": [{\"name\": \"VIB / раттлины\", \"level\": \"Личная сильная практика\", \"image\": \"data:image/webp;base64,\", \"where\": \"Карьер ГРЭС, Ахтубинск, Заволжское, Астрахань\", \"evidence\": \"На карьере ГРЭС все 4 щуки пришли только на VIB. В Ахтубинске небольшие шумные VIB дали серию окуня и жереха; в Астрахани городская точка дала серию щук.\", \"setup\": \"Тонущая приманка; вести у дна или немного выше. На карьере сработала равномерная проводка с рывками.\", \"develop\": \"Собрать классификацию по размеру, массе, глубине, шумности и типу падения.\"}, {\"name\": \"Живец на отводном поводке\", \"level\": \"Личный фирменный метод\", \"image\": \"data:image/webp;base64,\", \"where\": \"Астраханская область\", \"evidence\": \"Надёжный метод по судаку. На ерике Казачий были хорошие судаки; однажды таким же способом у дна был пойман жерех около 3.5 кг.\", \"setup\": \"Основной шнур → вертлюг → отдельный поводок груза 20–40 см + поводок приманки 70–100 см; офсет 4/0; узкий живец около 7 см.\", \"develop\": \"Зафиксировать веса грузов по течению и оптимальную длину поводков на разных глубинах.\"}, {\"name\": \"Джиг\", \"level\": \"Уверенно, но есть куда углубляться\", \"image\": \"data:image/webp;base64,\", \"where\": \"Крупные реки, Обь, Астрахань\", \"evidence\": \"Исторический рабочий диапазон примерно 7–28 г. Пользователь хочет глубже развить именно джиг как базовый поиск хищника.\", \"setup\": \"Подбор веса сначала под контроль дна и течение, а не под формальный тест удилища.\", \"develop\": \"Системно отработать ступеньку, волочение, короткие подрывы, большие приманки и ночь.\"}, {\"name\": \"Воблеры\", \"level\": \"Уверенная практика\", \"image\": \"data:image/webp;base64,\", \"where\": \"Щучьи участки, растительность, мелководье\", \"evidence\": \"В Красном Яру 2022 воблеры были удобнее джига из-за растительности; по щуке метод рабочий.\", \"setup\": \"Выбор по заглублению и плавучести должен быть привязан к реальной глубине и наличию травы.\", \"develop\": \"Сделать визуальную классификацию minnow / crank / shad / topwater и по заглублению.\"}, {\"name\": \"Металл: колебалки / вертушки\", \"level\": \"Есть опыт, нужно систематизировать\", \"image\": \"data:image/webp;base64,\", \"where\": \"Жерех, щука, течение\", \"evidence\": \"Перспективно для дальнего заброса и активного поиска; пользователь хочет развивать этот класс приманок.\", \"setup\": \"Вес и профиль выбирать под дальность, горизонт и скорость течения.\", \"develop\": \"Собрать таблицу: дальность, скорость падения, глубина, устойчивость на струе.\"}, {\"name\": \"Фидер\", \"level\": \"Регулярная практика\", \"image\": \"data:image/webp;base64,\", \"where\": \"Реки, озёра, ерики\", \"evidence\": \"Почти каждая многодневная поездка включает фидер. Цели: карп, карась, буффало, плотва, сазан.\", \"setup\": \"Основная задача — кормовая точка, темп и дистанция; метод-фидер есть в арсенале, но пока почти не использовался.\", \"develop\": \"Разнести классический фидер и метод-фидер как отдельные сценарии.\"}], \"gear\": [{\"name\": \"Freestyle Walker FMS694M\", \"kind\": \"Travel-спиннинг\", \"spec\": \"1/4–3/4 oz (~7–21 г), line 10–16 lb\", \"status\": \"Подтверждено по маркировке\", \"use\": \"Лёгкий/средний джиг, воблеры, VIB и мобильная командировочная рыбалка.\"}, {\"name\": \"PureLure Sharpen RH-S704H-XF\", \"kind\": \"Travel-спиннинг\", \"spec\": \"7–40 г, line 8–20 lb\", \"status\": \"Подтверждено по маркировке\", \"use\": \"Более тяжёлый джиг, течение, крупные приманки.\"}, {\"name\": \"Катушка 2500\", \"kind\": \"Безынерционная\", \"spec\": \"Марка/модель записана неуверенно: Shimano «Technicum/technical?»\", \"status\": \"Нужна фото-верификация\", \"use\": \"Не фиксировать точную модель до фотографии маркировки.\"}, {\"name\": \"Катушка 4000\", \"kind\": \"Безынерционная\", \"spec\": \"Запись: Sedmar/Bearking 2021 Pro 2 HJ4000S\", \"status\": \"Нужна фото-верификация\", \"use\": \"Тяжёлая речная работа и запас мощности.\"}, {\"name\": \"Надувная лодка + электромотор 40 lb\", \"kind\": \"Лодочный комплект\", \"spec\": \"Китайский электромотор, лодка резиновая/надувная\", \"status\": \"В эксплуатации\", \"use\": \"Активный поиск на многодневных поездках.\"}, {\"name\": \"Бюджетный эхолот Lucky\", \"kind\": \"Эхолот\", \"spec\": \"Точная модель пока не внесена\", \"status\": \"В эксплуатации\", \"use\": \"Базовый поиск глубины и структуры; полезно позднее зафиксировать модель и частоту датчика.\"}, {\"name\": \"3 фидера\", \"kind\": \"Фидерный комплект\", \"spec\": \"Модели пока не внесены\", \"status\": \"В эксплуатации\", \"use\": \"Регулярно используются в многодневных поездках.\"}, {\"name\": \"Забродные штаны по пояс\", \"kind\": \"Экипировка\", \"spec\": \"Waist waders\", \"status\": \"В эксплуатации\", \"use\": \"Полезны на мелководных участках и при работе с лодкой.\"}], \"lures\": [{\"name\": \"Серебристый тонущий VIB\", \"type\": \"VIB / раттлин\", \"size\": \"ориентировочно 63–65 мм\", \"status\": \"Размер оценён по фото, ±2–3 мм\", \"evidence\": \"Одна из двух приманок, на которые были все поклёвки щуки на карьере ГРЭС.\", \"image\": \"data:image/webp;base64,\"}, {\"name\": \"Белый VIB с красной головой\", \"type\": \"VIB / раттлин\", \"size\": \"ориентировочно 52–55 мм\", \"status\": \"Размер оценён по фото, ±2–3 мм\", \"evidence\": \"Вторая рабочая приманка той же успешной сессии на карьере ГРЭС.\", \"image\": \"data:image/webp;base64,\"}, {\"name\": \"Силикон 2.5–3.5\\\" на отводном\", \"type\": \"Мягкая приманка\", \"size\": \"2.5–3.5 дюйма\", \"status\": \"Рабочий диапазон\", \"evidence\": \"Подходит для текущей и глубокой речной работы; в Нижневартовске обсуждалась как базовая подача на отводном.\", \"image\": \"data:image/webp;base64,\"}, {\"name\": \"Живец около 7 см\", \"type\": \"Натуральная приманка\", \"size\": \"узкий профиль ~7 см\", \"status\": \"Личная практика\", \"evidence\": \"Лучше меньше крутит поводок; один из ключевых элементов фирменной астраханской схемы.\", \"image\": \"data:image/webp;base64,\"}], \"research_notes\": [{\"title\": \"Избербаш: почему 23.08.2020 был взрыв клёва\", \"status\": \"Открытая гипотеза\", \"grade\": \"D → требуется A/B\", \"body\": \"Нужно проверить, действительно ли шторм, направление ветра, волна и изменение прибрежной циркуляции концентрировали корм у каменисто-песчаной кромки.\", \"next\": \"Сопоставить 21–24.08.2020 с 05–07.10.2025 по ветру, волне, SST, давлению, осадкам и мутности.\"}, {\"title\": \"Заволжское 2023: почему полный провал при знакомых местах\", \"status\": \"Приоритетное исследование\", \"grade\": \"Личный факт + нужна гидрология\", \"body\": \"Поздний сентябрь 2023 дал практически ноль и по хищнику, и по мирной рыбе, хотя внешний вид условий не казался экстремальным.\", \"next\": \"Сравнить уровень, расход, температуру и тренд воды с августом 2021 и июлем–августом 2022.\"}, {\"title\": \"Красный Яр 2023: экстремально высокая вода\", \"status\": \"Сильная рабочая гипотеза\", \"grade\": \"Личный факт + гидрология\", \"body\": \"В конце мая 2023 вода была намного выше обычной, течение очень сильным, а рыбалка почти нулевая даже на мелководье.\", \"next\": \"Не обобщать как «май плохой». Найти уровни и расход на конкретные даты.\"}, {\"title\": \"Паразит у окуня в Астрахани\", \"status\": \"Научное подтверждение присутствия\", \"grade\": \"A\", \"body\": \"Исследование 2026 года по окуню из Волги в Астрахани морфологически и молекулярно описало личинок Eustrongylides excisus; 37 из 80 рыб были предварительно отнесены к заражённым по видимым личинкам. Это не означает популяционную распространённость 46%.\", \"next\": \"В приложении хранить как подтверждение присутствия паразита, а не как процент заражённости всей астраханской популяции.\"}, {\"title\": \"Сулак 2025: роль высокой воды и сбросов\", \"status\": \"Открытая гипотеза\", \"grade\": \"D → требуется гидрология\", \"body\": \"Пользователь застал серую высокую воду и очень сильное течение; даже местный рыбак отказался ловить в этих условиях.\", \"next\": \"Поднять уровни/расход и режим гидроузлов на 05–11.10.2025.\"}], \"sources\": [{\"title\": \"Правила рыболовства Западно-Сибирского бассейна\", \"grade\": \"A\", \"date\": \"ред. 08.06.2026\", \"note\": \"Текущая нормативная база для ХМАО. Изменения приказа №395 вступили в силу 08.09.2026.\", \"url\": \"https://www.consultant.ru/document/cons_doc_LAW_379425/a24338e38a941a53cef9e06c80f7d28293714693/\"}, {\"title\": \"Ограничения 2026 по Волжско-Каспийскому бассейну\", \"grade\": \"A\", \"date\": \"2026\", \"note\": \"В 2026 запрещено любительское рыболовство воблы в Каспии и Волге/водотоках Астраханской области; по плотве есть отдельные районные ограничения.\", \"url\": \"https://base.garant.ru/412792471/\"}, {\"title\": \"Eustrongylides excisus у окуня из Волги, Астрахань\", \"grade\": \"A\", \"date\": \"2026\", \"note\": \"Рецензируемая работа с морфологическим и молекулярным подтверждением паразита у европейского окуня.\", \"url\": \"https://pubmed.ncbi.nlm.nih.gov/42575603/\"}, {\"title\": \"Личные полевые записи пользователя\", \"grade\": \"B/C\", \"date\": \"2020–2026\", \"note\": \"Высокий вес для конкретного рыболова и точек; не подменяют текущую гидрологию и свежие условия.\", \"url\": \"\"}], \"knowledge\": [{\"title\": \"Как приложение оценивает доказательства\", \"body\": \"A — официальные/научные источники; B — несколько независимых практических подтверждений; C — сильный локальный автор; D — одиночная гипотеза/сообщение; E — SEO и непрозрачные «прогнозы клёва».\", \"tag\": \"Методология\"}, {\"title\": \"Полевой протокол новой точки\", \"body\": \"Координаты → фото фронт/лево/право → вес груза → время падения → снос → характер дна → горизонт поклёвки. Сначала проверяем структуру и положение рыбы, потом цвет приманки.\", \"tag\": \"Практика\"}, {\"title\": \"Что важнее давления\", \"body\": \"Само атмосферное давление не рассматривается как магический фактор. Гораздо полезнее фронт, ветер, свет, перемешивание, температура воды, расход и положение кормовой рыбы.\", \"tag\": \"Наука / практика\"}, {\"title\": \"Луна — низкий приоритет\", \"body\": \"Фаза луны не будет иметь большого веса в алгоритме без личного статистического сигнала. Сначала — гидрология, температура, свет, ветер, структура и свежие отчёты.\", \"tag\": \"Методология\"}]};\n\nfunction renderWaters(){\n  const host = document.getElementById('watersList'); host.innerHTML = '';\n  PROJECT_DB.waterbodies.forEach(w=>{\n    const c = el('div','knowledge-card');\n    c.innerHTML = `<div class=\"kimg\"><img loading=\"lazy\" src=\"${w.image}\" alt=\"${w.name}\"></div><div class=\"kbody\">\n      <div class=\"khead\"><div><h4>${w.name}</h4><div class=\"stype\">${w.region}</div></div><div class=\"kstatus\">${w.status}</div></div>\n      <div class=\"klabel\">Координаты</div><div class=\"kline\">${w.coords}</div>\n      <div class=\"kchips\">${w.targets.map(x=>`<span>${x}</span>`).join('')}</div>\n      <div class=\"klabel\">Подтверждённые факты</div><div class=\"kline\">${w.facts.map(x=>`• ${x}`).join('<br>')}</div>\n      <div class=\"klabel\">Рабочая гипотеза</div><div class=\"kline\">${w.hypothesis}</div>\n      <div class=\"klabel\">Что проверять дальше</div><div class=\"kline\">${w.next}</div></div>`;\n    c.classList.add('interactive-card');\n    c.addEventListener('click', ()=>openWaterbodyDetail(w,'waters'));\n    c.querySelector('.kbody').insertAdjacentHTML('beforeend','<div class=\"card-openhint\">Открыть карточку →</div>');\n    host.appendChild(c);\n  });\n}\nfunction renderMethods(){\n  const host = document.getElementById('methodsList'); host.innerHTML = '';\n  PROJECT_DB.methods.forEach(x=>{\n    const c = el('div','knowledge-card');\n    c.innerHTML = `<div class=\"kimg\"><img loading=\"lazy\" src=\"${x.image}\" alt=\"${x.name}\"></div><div class=\"kbody\">\n      <div class=\"khead\"><div><h4>${x.name}</h4><div class=\"stype\">${x.level}</div></div></div>\n      <div class=\"klabel\">Где подтверждено</div><div class=\"kline\">${x.where}</div>\n      <div class=\"klabel\">Личный материал</div><div class=\"kline\">${x.evidence}</div>\n      <div class=\"klabel\">Базовая схема</div><div class=\"kline\">${x.setup}</div>\n      <div class=\"klabel\">Что развиваем</div><div class=\"kline\">${x.develop}</div></div>`;\n    host.appendChild(c);\n  });\n}\nfunction renderGear(){\n  const host = document.getElementById('gearList');\n  const excluded = ['Freestyle Walker FMS694M','PureLure Sharpen RH-S704H-XF','3 фидера'];\n  return window.PersonalGearUI.render(host, {legacy:PROJECT_DB.gear.filter(x=>!excluded.includes(x.name))});\n}\nfunction renderLures(){\n  const host = document.getElementById('luresList'); host.innerHTML = '';\n  PROJECT_DB.lures.forEach(x=>{\n    const c = el('div','knowledge-card');\n    c.innerHTML = `<div class=\"kimg\"><img loading=\"lazy\" src=\"${x.image}\" alt=\"${x.name}\"></div><div class=\"kbody\">\n      <div class=\"khead\"><div><h4>${x.name}</h4><div class=\"stype\">${x.type}</div></div></div>\n      <div class=\"kchips\"><span>${x.size}</span><span>${x.status}</span></div>\n      <div class=\"klabel\">Практическое подтверждение</div><div class=\"kline\">${x.evidence}</div></div>`;\n    host.appendChild(c);\n  });\n}\nfunction renderKnowledge(){\n  const host = document.getElementById('knowledgeList'); host.innerHTML = '';\n  document.getElementById('knowledgeSpecies')?.remove();\n  const pack = window.FISH_KNOWLEDGE_V1;\n  const available = (pack?.cards || []).filter(card=>DATA.fishCatalog.some(f=>f.name===card.catalog_name));\n  if(available.length){\n    const block = el('section','card'); block.id = 'knowledgeSpecies';\n    const ids = new Set(available.flatMap(card=>card.sections.flatMap(s=>s.claim_ids)));\n    const sources = new Set((pack.claims || []).filter(c=>ids.has(c.id)).flatMap(c=>c.source_ids));\n    block.innerHTML = `<div class=\"card-title\"><h3>ЗНАНИЯ ПО ВИДАМ РЫБ</h3><div class=\"section-count\">${available.length}</div></div><p>${ids.size} утверждений · ${sources.size} источника. Откройте вид: у каждого утверждения указаны источник и границы применимости.</p>`;\n    const grid = el('div','kb-species-grid');\n    available.forEach(card=>{\n      const claimIds = new Set(card.sections.flatMap(s=>s.claim_ids));\n      const sourceIds = new Set((pack.claims || []).filter(c=>claimIds.has(c.id)).flatMap(c=>c.source_ids));\n      const item = el('button','simple-card interactive-card kb-species-link'); item.type='button';\n      item.innerHTML = `<h4>${fish25Esc(card.catalog_name)}</h4><div class=\"stype\">${fish25Esc(card.scientific_name)}</div><p>Разделов: ${card.sections.length} · утверждений: ${claimIds.size} · источников: ${sourceIds.size}</p><span>Открыть материалы →</span>`;\n      item.addEventListener('click',()=>openFish(card.catalog_name,'knowledge')); grid.appendChild(item);\n    });\n    block.appendChild(grid);\n    const note=el('p'); note.textContent=`Остальные виды каталога (${DATA.fishCatalog.length-available.length}) ещё проходят перенос в структуру со связанными источниками.`; block.appendChild(note);\n    const style=el('style'); style.textContent='.kb-species-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:12px;margin:16px 0}.kb-species-link{font:inherit;color:inherit;text-align:left;width:100%;cursor:pointer;background:linear-gradient(145deg,#0b2538,#061822)}.kb-species-link span{color:#72caff;font-size:12px}.kb-species-link:focus-visible{outline:2px solid #72caff;outline-offset:3px}'; block.appendChild(style);\n    host.closest('.card').before(block);\n  }\n  PROJECT_DB.knowledge.forEach(x=>{\n    const c = el('div','simple-card');\n    c.innerHTML = `<h4>${x.title}</h4><div class=\"stype\">${x.tag}</div><p>${x.body}</p>`;\n    host.appendChild(c);\n  });\n}\nfunction renderResearchBase(){\n  const host = document.getElementById('researchBaseList'); host.innerHTML = '';\n  PROJECT_DB.research_notes.forEach(x=>{\n    const c = el('div','simple-card');\n    c.innerHTML = `<div class=\"khead\"><div><h4>${x.title}</h4><div class=\"stype\">${x.grade}</div></div><div class=\"kstatus\">${x.status}</div></div><p>${x.body}</p><div class=\"klabel\">Следующий шаг</div><p>${x.next}</p>`;\n    host.appendChild(c);\n  });\n  const sHost = document.getElementById('researchSources'); sHost.innerHTML = '';\n  PROJECT_DB.sources.forEach(s=>{\n    const c = el('div','sourcecard');\n    const link = s.url ? `<a class=\"source-link\" href=\"${s.url}\" target=\"_blank\" rel=\"noopener\">Открыть источник ↗</a>` : '';\n    c.innerHTML = `<div class=\"sname\">${s.title}</div><div class=\"smeta\">Класс ${s.grade} · ${s.date}</div><div class=\"snote\">${s.note}</div>${link}`;\n    sHost.appendChild(c);\n  });\n}\n\n\nconst REGION_DETAIL = {\"Нижневартовск\": {\"image\": \"data:image/webp;base64,\", \"origin\": \"Нижневартовск\", \"summary\": \"Рабочая ветка береговой и карьерной рыбалки. Уже есть подтверждённая точка по щуке и несколько разведанных береговых участков.\", \"status\": \"Активный регион\", \"targets\": [\"Щука\", \"Судак\", \"Хищник\"], \"methods\": [\"VIB / раттлины\", \"Джиг\", \"Отводной поводок\"], \"water_terms\": [\"ХМАО\"], \"diary_terms\": [\"нижневарт\", \"излучинск\"], \"research\": [\"Промерить профиль карьера ГРЭС и подтвердить привязку щуки к близкой бровке.\", \"Собрать свежую гидрологию Оби и связать её с береговыми выходами хищника.\", \"Развести по отдельным картам: городской берег, Вах/Излучинск, карьер ГРЭС.\"]}, \"Астраханская область\": {\"image\": \"data:image/webp;base64,";